llargada = float(input("Introdueix la llargada del cuadrat: ")) #creem una variable que se diu llargada i que contidra el valor del llargada del cuadrat
alçada = float(input("Introdueix l'alçada del cuadrat: ")) #creem una variable que se diu alçada i que contidra el valor del alçada del cuadrat
superfice = llargada * alçada #creem una variable que se diu superfice i que contidra el valor del superfice del cuadrat
print(superfice) #mostrem per pantalla el superfice del cuadrat